async function checkpointActiveTask(
  input: CheckpointActiveTaskInput,
): Promise<CheckpointActiveTaskOutput> {
  const checkpointId = input.checkpointId.trim();
  if (checkpointId.length === 0 || checkpointId.length > 200) {
    throw new ContinuityServiceError("VALIDATION_ERROR", "checkpointId must contain between 1 and 200 characters");
  }
  const summary = input.task.state === "clear" ? input.task.outcome.trim() : input.task.summary.trim();
  if (summary.length === 0 || summary.length > MAX_ACTIVE_TASK_TEXT_CHARS) {
    throw new ContinuityServiceError(
      "VALIDATION_ERROR",
      `task summary must contain between 1 and ${MAX_ACTIVE_TASK_TEXT_CHARS} characters`,
    );
  }
  if (input.task.state !== "clear") {
    const nextStep = input.task.nextStep.trim();
    if (nextStep.length === 0 || nextStep.length > MAX_ACTIVE_TASK_TEXT_CHARS) {
      throw new ContinuityServiceError(
        "VALIDATION_ERROR",
        `task next step must contain between 1 and ${MAX_ACTIVE_TASK_TEXT_CHARS} characters`,
      );
    }
  }
  if ((input.task.details?.length ?? 0) > MAX_ACTIVE_TASK_DETAILS_CHARS) {
    throw new ContinuityServiceError(
      "VALIDATION_ERROR",
      `task details must contain at most ${MAX_ACTIVE_TASK_DETAILS_CHARS} characters`,
    );
  }

  const paths = resolveBoundContinuityWorkspace(input);
  return withWorkspaceMutationLock(paths, async () => {
    const before = await readCurrent(paths);
    if (before.kind === "malformed") throw new ContinuityServiceError("CONTINUITY_MALFORMED", before.message);

    const eventId = checkpointEventId(paths.workspace.key, checkpointId);
    const events = await readAllEvents(paths);
    if (events.kind === "malformed") throw new ContinuityServiceError("CONTINUITY_MALFORMED", events.message);
    const existing = events.kind === "ok" ? events.events.find((event) => event.id === eventId) : undefined;
    const details = checkpointDetails(input.task);
    if (existing && !checkpointEventMatches(existing, input.task, details)) {
      throw new ContinuityServiceError(
        "VALIDATION_ERROR",
        `checkpointId ${checkpointId} was already used for different task content`,
      );
    }
    if (input.task.state === "clear" && before.kind === "missing" && !existing) {
      throw new ContinuityServiceError("CONTINUITY_NOT_INITIALIZED", "Cannot clear an active task before Continuity exists");
    }
    if (input.task.state === "clear" && before.kind === "ok" && before.value.active_task === null && !existing) {
      throw new ContinuityServiceError("VALIDATION_ERROR", "No active task is available to clear");
    }

    const priorTask = before.kind === "ok" ? before.value.active_task : null;
    const eventInput: EventInput = {
      type: input.task.state === "clear" ? "correction" : "next_action",
      status: "active",
      summary: input.task.state === "clear" ? input.task.outcome : input.task.summary,
      details,
      supersedes:
        input.task.state !== "clear" && priorTask && priorTask.event_id !== eventId ? [priorTask.event_id] : [],
      resolves: input.task.state === "clear" && priorTask ? [priorTask.event_id] : [],
      related_events: priorTask ? [priorTask.event_id] : [],
    };
    const event =
      existing ??
      (await recordEvent(paths, eventInput, {
        source: boundEventSource(input.binding, input.source),
        now: input.now,
        id: () => eventId,
      }));

    const afterRecord = await readCurrent(paths);
    if (afterRecord.kind !== "ok") {
      throw new ContinuityServiceError("CONTINUITY_MALFORMED", afterRecord.message);
    }
    const desired: ActiveTask | null =
      input.task.state === "clear"
        ? null
        : activeTaskSchema.parse({
            event_id: event.id,
            recorded_at: event.effective_at ?? event.created_at,
            summary: input.task.summary,
            state: input.task.state,
            next_step: input.task.nextStep,
          });
    const taskChanged = JSON.stringify(afterRecord.value.active_task) !== JSON.stringify(desired);
    const nextInput = currentFrameInput(afterRecord.value);
    nextInput.active_task = desired;
    nextInput.next_actions = nextInput.next_actions.filter((item) => item.event_id !== event.id);
    const changed = taskChanged || nextInput.next_actions.length !== afterRecord.value.next_actions.length;
    const frame = changed
      ? await updateCurrent(paths, nextInput, { now: input.now })
      : afterRecord.value;

    return {
      paths,
      workspace: paths.workspace,
      event,
      frame,
      rendered: renderContinuityFrame(frame),
      changed,
      binding: workContextBindingView(input.binding),
    };
  }, { now: input.now });
}

async function handleContinuityCheckpointTask(
  args: ContinuityCheckpointTaskArgs,
  dependencies: BoundHandlerDependencies = {},
): Promise<CallToolResult> {
  try {
    const binding = await requireMutationBinding(args, dependencies, "anvil_continuity_checkpoint_task");
    return jsonResult(
      continuityCheckpointTaskOutputSchema,
      checkpointTaskOutput(
        await checkpointActiveTask({
          binding,
          stateRoot: dependencies.stateRoot,
          bindingNow: dependencies.now,
          checkpointId: args.checkpointId,
          task: args.task,
          source: {
            kind: "codex_mcp",
            ...(args.source?.turnId !== undefined ? { turn_id: args.source.turnId } : {}),
            ...(args.source?.description !== undefined ? { description: args.source.description } : {}),
          },
        }),
      ),
    );
  } catch (error) {
    return errorResult(error);
  }
}

function checkpointTaskOutput(
  result: CheckpointActiveTaskOutput,
): z.input<typeof continuityCheckpointTaskOutputSchema> {
  return {
    workspace: result.workspace,
    binding: result.binding,
    event: result.event,
    frame: result.frame,
    rendered: result.rendered,
    changed: result.changed,
  };
}

function checkpointDetails(input: CheckpointActiveTaskInput["task"]): string {
  const lines =
    input.state === "clear"
      ? [`Task checkpoint: clear`, `Outcome: ${input.outcome}`]
      : [`Task checkpoint: ${input.state}`, `Next step: ${input.nextStep}`];
  if (input.details) lines.push("", input.details);
  return lines.join("\n");
}

type CheckpointActiveTaskInput = BoundContinuityMutationOptions & {
  checkpointId: string;
  task:
    | {
        state: ActiveTaskState;
        summary: string;
        nextStep: string;
        details?: string;
      }
    | {
        state: "clear";
        outcome: string;
        details?: string;
      };
  source?: EventSource;
  now?: Clock;
};

function deriveContinuityPaths({ stateRoot, workspace }: { stateRoot: string; workspace: WorkspaceRef }): ContinuityPaths {
  if (!stateRoot || typeof stateRoot !== "string") throw new Error("stateRoot must be a non-empty string");
  if (!workspace || typeof workspace !== "object") throw new Error("workspace must be supplied");

  const continuityRoot = join(stateRoot, CONTINUITY_DIR_NAME);
  const workspaceDir = join(continuityRoot, WORKSPACES_DIR_NAME, workspace.key);
  return {
    workspace,
    stateRoot,
    continuityRoot,
    indexPath: join(continuityRoot, "index.json"),
    workspaceDir,
    currentPath: join(workspaceDir, "current.json"),
    eventsPath: join(workspaceDir, "events.jsonl"),
    workspaceMutationKey: join(workspaceDir, ".mutation.lock"),
  };
}

function renderActiveTask(activeTask: ActiveTask | null): string[] {
  if (!activeTask) return ["Active task:", "- none"];
  return [
    "Active task:",
    `- [${activeTask.event_id}] (recorded ${activeTask.recorded_at.slice(0, 10)}) ${truncateText(activeTask.summary)}`,
    `- state: ${activeTask.state}`,
    `- next step: ${truncateText(activeTask.next_step)}`,
  ];
}

async function readCurrent(paths: ContinuityPaths): Promise<ReadResult<CurrentFrame>> {
  const json = await readJson(paths.currentPath);
  if (json.kind !== "ok") return json;
  const validated = validateCurrentFrame(json.value);
  if (!validated.ok) return { kind: "malformed", path: paths.currentPath, message: validated.message };
  return { kind: "ok", value: validated.value };
}

async function recordEventUnlocked(
  paths: ContinuityPaths,
  input: EventInput,
  options: {
    source?: EventSource;
    now?: Clock;
    id?: IdGenerator;
  } = {},
): Promise<ContinuityEvent> {
  const eventInput = ensureEventInput(input);
  const eventId = (options.id ?? newEventId)();
  const now = (options.now ?? nowIso)();
  const source = ensureEventSource(options.source ?? { kind: "manual" });

  const current = await readCurrent(paths);
  let currentFrame: CurrentFrame;
  if (current.kind === "ok") {
    currentFrame = current.value;
  } else if (current.kind === "missing") {
    currentFrame = await initWorkspaceUnlocked(paths, bootstrapFrameInput(eventInput, eventId, now), { now: () => now });
  } else {
    throw new Error(`Cannot record event without valid current frame: ${current.message}`);
  }

  await writeFile(paths.eventsPath, "", { encoding: "utf8", flag: "a" });
  const event: ContinuityEvent = {
    version: EVENT_SCHEMA_VERSION,
    id: eventId,
    created_at: now,
    effective_at: now,
    ...eventInput,
    workspace: currentFrame.workspace,
    source,
  };

  await appendJsonLine(paths.eventsPath, event);
  return event;
}

async function updateCurrentUnlocked(
  paths: ContinuityPaths,
  input: CurrentFrameInput,
  options: { now?: Clock } = {},
): Promise<CurrentFrame> {
  const current = await readCurrent(paths);
  if (current.kind !== "ok") throw new Error(`Cannot update current frame: ${current.message}`);

  const frameInput = ensureCurrentInput(input);
  const next: CurrentFrame = {
    version: CURRENT_SCHEMA_VERSION,
    updated_at: (options.now ?? nowIso)(),
    workspace: current.value.workspace,
    ...frameInput,
    active_task: frameInput.active_task ?? null,
  };
  await writeJsonAtomic(paths.currentPath, next);
  return next;
}

async function updateCurrent(
  paths: ContinuityPaths,
  input: CurrentFrameInput,
  options: { now?: Clock } = {},
): Promise<CurrentFrame> {
  return withWorkspaceMutationLock(paths, () => updateCurrentUnlocked(paths, input, options), { now: options.now });
}

function currentFrameInput(frame: CurrentFrame): CurrentFrameInput {
  return {
    operating_mode: frame.operating_mode,
    intent: frame.intent,
    quality_bar: frame.quality_bar,
    permission_envelope: frame.permission_envelope,
    active_task: frame.active_task,
    active_decisions: frame.active_decisions,
    open_questions: frame.open_questions,
    next_actions: frame.next_actions,
    continuity_notes: frame.continuity_notes,
  };
}

async function runContextHook(): Promise<void> {
  let input: CodexHookInput = {};
  const text = await readStdin();
  if (text.trim().length > 0) {
    try {
      input = JSON.parse(text);
    } catch {
      input = {};
    }
  }

  const cwd = typeof input.cwd === "string" && input.cwd.trim().length > 0 ? input.cwd : process.cwd();
  const hookEventName = input.hook_event_name ?? "SessionStart";
  if (hookEventName === "PreToolUse") {
    if (isDirectCodexContextHookProbe(input.tool_name, input.tool_input)) {
      const reason =
        "HOST_LIFECYCLE_PROBE_BLOCKED: Agent-issued Codex lifecycle-hook probes are forbidden. Use the context injected by the registered host hook.";
      process.stderr.write(`[anvil codex hook] ${reason}\n`);
      process.stdout.write(`${JSON.stringify(codexPreToolUseOutput({ decision: "deny", reason }))}\n`);
      return;
    }
    const toolName = workContextBoundToolName(input.tool_name);
    if (!toolName) {
      return;
    }
    if (!isRecord(input.tool_input)) {
      const reason = "WORK_CONTEXT_MISMATCH: Anvil mutation tool input must be an object";
      await tryRecordHookRejection("WORK_CONTEXT_MISMATCH", toolName);
      process.stderr.write(`[anvil work context] ${reason}\n`);
      process.stdout.write(`${JSON.stringify(codexPreToolUseOutput({ decision: "deny", reason }))}\n`);
      return;
    }
    try {
      const binding = await refreshCodexWorkContext({ cwd: input.cwd, sessionId: input.session_id });
      let trustedInput = stripCallerMutationAuthority(input.tool_input, toolName);
      if (toolName === "anvil_skill_invocation_log") {
        const {
          host: _callerHost,
          sessionId: _callerSessionId,
          turnId: _callerTurnId,
          messageId: _callerMessageId,
          ...skillInput
        } = trustedInput;
        const turnId = optionalHookIdentifier(input.turn_id);
        const messageId = optionalHookIdentifier(input.message_id);
        trustedInput = {
          ...skillInput,
          ...(turnId ? { turnId } : {}),
          ...(messageId ? { messageId } : {}),
        };
      }
      process.stdout.write(
        `${JSON.stringify(
          codexPreToolUseOutput({
            decision: "allow",
            updatedInput: { ...trustedInput, bindingId: binding.id },
          }),
        )}\n`,
      );
      return;
    } catch (error) {
      if (!(error instanceof WorkContextError)) throw error;
      await tryRecordHookRejection(error.code, toolName);
      writeWorkContextDiagnostic(error);
      const reason = `${error.code}: ${error.message}`;
      process.stdout.write(`${JSON.stringify(codexPreToolUseOutput({ decision: "deny", reason }))}\n`);
      return;
    }
  }
  if (hookEventName === "Stop") {
    if (input.stop_hook_active === true) return;

    let binding;
    try {
      binding = await requireCodexWorkContext({ cwd: input.cwd, sessionId: input.session_id });
    } catch (error) {
      if (!(error instanceof WorkContextError)) throw error;
      writeWorkContextDiagnostic(error);
      return;
    }

    const closure = await readBrainMaintenanceClosure({
      cwd: binding.collaboration_space.root,
      env: process.env,
      sessionId: binding.session_id,
    });
    if (closure.kind === "malformed") {
      const reason =
        `Brain maintenance closure cannot be verified because the usage journal is malformed: ${closure.message}`;
      process.stderr.write(`[anvil brain maintenance] ${reason}\n`);
      process.stdout.write(`${JSON.stringify({ decision: "block", reason })}\n`);
      return;
    }
    if (closure.kind === "ok" && closure.unresolved.length > 0) {
      const incidents = closure.unresolved
        .slice(0, 3)
        .map((record) => `${record.id} (${record.event}${record.pages?.[0] ? `: ${record.pages[0]}` : ""})`)
        .join(", ");
      const omitted = closure.unresolved.length - Math.min(closure.unresolved.length, 3);
      const reason = [
        `Brain maintenance is not closed for this session: ${incidents}${omitted > 0 ? `, plus ${omitted} more` : ""}.`,
        "Resolve each incident in this current main session before handoff: update, verify, and commit Brain, then record an updated event related to the incident ID; or record an evidence-backed not_needed event related to it when Steward review finds no Brain change is warranted.",
        "Do not launch a child agent, model, judge, deferred handoff, or maintenance queue.",
      ].join(" ");
      process.stdout.write(`${JSON.stringify({ decision: "block", reason })}\n`);
    }
    return;
  }
  if (hookEventName === "UserPromptSubmit") {
    let workContextDiagnostic = "";
    try {
      await requireCodexWorkContext({ cwd: input.cwd, sessionId: input.session_id });
    } catch (error) {
      if (!(error instanceof WorkContextError)) throw error;
      writeWorkContextDiagnostic(error);
      workContextDiagnostic = renderWorkContextDiagnostic(error);
    }
    if (process.env.ANVIL_BRAIN_CONTEXT === "off") {
      if (!workContextDiagnostic) {
        await tryRecordPromptRecallTelemetry({ cwd, lifecycle: input, event: "disabled" });
      }
      process.stdout.write(
        `${JSON.stringify(
          codexAdditionalContext("UserPromptSubmit", workContextDiagnostic),
        )}\n`,
      );
      return;
    }
    const startedAt = performance.now();
    const envelope = await planContext({
      lifecycle: "prompt",
      cwd,
      prompt: typeof input.prompt === "string" ? input.prompt : "",
      ...(input.temporal !== undefined ? { temporal: input.temporal } : {}),
      host: "codex",
      sessionId: optionalHookIdentifier(input.session_id),
      reservedBytes: Buffer.byteLength(workContextDiagnostic, "utf8"),
    });
    const telemetryBrain = telemetryBrainFromEnvelope(envelope);
    if (!workContextDiagnostic) {
      await tryRecordPromptRecallTelemetry({
        cwd,
        lifecycle: input,
        event: promptRecallOutcomeFromEnvelope(envelope),
        durationMs: Math.round(performance.now() - startedAt),
        brain: telemetryBrain,
      });
    }
    writeBrainDiagnostics(envelope);
    const promptContext = [envelope.markdown, workContextDiagnostic]
      .filter((value) => value.length > 0)
      .join("\n\n");
    process.stdout.write(`${JSON.stringify(codexAdditionalContext("UserPromptSubmit", promptContext))}\n`);
    return;
  }
  if (hookEventName !== "SessionStart") {
    fail("anvil codex context-hook supports only SessionStart, UserPromptSubmit, PreToolUse, and Stop hook events");
  }

  let binding;
  try {
    binding = await bindCodexWorkContext({
      cwd: input.cwd,
      sessionId: input.session_id,
      source: input.source,
    });
  } catch (error) {
    if (!(error instanceof WorkContextError)) throw error;
    writeWorkContextDiagnostic(error);
    process.stdout.write(
      `${JSON.stringify(codexAdditionalContext("SessionStart", renderWorkContextDiagnostic(error)))}\n`,
    );
    return;
  }

  const paths = resolveWorkspace({ cwd });
  const current = await readCurrent(paths);
  let additionalContext;
  if (current.kind === "ok") {
    additionalContext = renderContinuityFrame(current.value);
  } else if (current.kind === "missing") {
    additionalContext = [
      "## Anvil Continuity Frame",
      "",
      "No Anvil continuity frame is initialized for this workspace yet.",
      "",
      "Do not invent continuity. Use current user instruction, current files, and live project evidence as the source of truth.",
      `State root: ${paths.stateRoot}`,
      `Workspace: ${paths.workspace.label ?? paths.workspace.key} (${paths.workspace.root})`,
    ].join("\n");
  } else {
    additionalContext = renderMalformedContinuityDiagnostic({
      path: current.path,
      message: current.message,
      workspace_key: paths.workspace.key,
    });
  }

  const workContext = renderWorkContext(binding);
  additionalContext = `${workContext}\n\n${additionalContext}`;
  const compactAdditionalContext = [
    "## Anvil Work Context",
    "",
    `Binding: ${binding.id} (${binding.status})`,
    `Collaboration space: ${binding.collaboration_space.label ?? binding.collaboration_space.key}`,
    "",
    "## Anvil Continuity Active Task",
    "",
    ...(current.kind === "ok"
      ? renderActiveTask(current.value.active_task)
      : ["Active task:", "- unavailable because Continuity is not readable"]),
    "",
    "## Anvil Continuity Frame",
    "",
    "[truncated; read Continuity through Anvil when orientation is uncertain]",
  ].join("\n");

  if (process.env.ANVIL_BRAIN_CONTEXT === "off") {
    process.stdout.write(
      `${JSON.stringify(codexAdditionalContext("SessionStart", withBootstrapPointer(additionalContext)))}\n`,
    );
    return;
  }

  const envelope = await planContext({
    lifecycle: contextLifecycle(input.source),
    cwd,
    host: "codex",
    sessionId: optionalHookIdentifier(input.session_id),
    reservedBytes: Buffer.byteLength(additionalContext.trimEnd(), "utf8") + 2,
  });
  writeBrainDiagnostics(envelope);
  const context = renderSessionStartContext({
    continuity: additionalContext,
    compactContinuity: compactAdditionalContext,
    brain: envelope.markdown,
    hardBytes: envelope.receipt.budget.hardBytes,
  });
  if (context.truncated) {
    process.stderr.write(
      "[anvil brain context] BRAIN_CONTEXT_BUDGET_VIOLATION: Context Harness output exceeded the reviewed host envelope. Recovery: Inspect the Recall Receipt and repair the producer-to-envelope budget contract.\n",
    );
  }
  process.stdout.write(`${JSON.stringify(codexAdditionalContext("SessionStart", context.markdown))}\n`);
}

