383	      status: "active",
384	      summary: input.task.state === "clear" ? input.task.outcome : input.task.summary,
385	      details,
386	      supersedes:
387	        input.task.state !== "clear" && priorTask && priorTask.event_id !== eventId ? [priorTask.event_id] : [],
388	      resolves: input.task.state === "clear" && priorTask ? [priorTask.event_id] : [],
389	      related_events: priorTask ? [priorTask.event_id] : [],
390	    };
391	    const event =
392	      existing ??
393	      (await recordEvent(paths, eventInput, {
