 30	export function deriveContinuityPaths({ stateRoot, workspace }: { stateRoot: string; workspace: WorkspaceRef }): ContinuityPaths {
 31	  if (!stateRoot || typeof stateRoot !== "string") throw new Error("stateRoot must be a non-empty string");
 32	  if (!workspace || typeof workspace !== "object") throw new Error("workspace must be supplied");
 33	
 34	  const continuityRoot = join(stateRoot, CONTINUITY_DIR_NAME);
 35	  const workspaceDir = join(continuityRoot, WORKSPACES_DIR_NAME, workspace.key);
 36	  return {
 37	    workspace,
 38	    stateRoot,
 39	    continuityRoot,
 40	    indexPath: join(continuityRoot, "index.json"),
 41	    workspaceDir,
 42	    currentPath: join(workspaceDir, "current.json"),
 43	    eventsPath: join(workspaceDir, "events.jsonl"),
 44	    workspaceMutationKey: join(workspaceDir, ".mutation.lock"),
 45	  };
 46	}
